// A fixed 32 MiB TSV ceiling is checked before every write.
#include "production_core_v1.hpp"
#include <iostream>
#include <sys/resource.h>
using namespace a19;

struct Roster {
 std::ifstream stream;
 explicit Roster(const std::string&path,uint64_t begin):stream(path,std::ios::binary){struct stat data{};require(stat(path.c_str(),&data)==0&&data.st_size==8ull*roster_rows&&bool(stream),"complete immutable original roster");stream.seekg(8*begin);require(bool(stream),"original range seek");}
 std::array<uint32_t,4>next(){unsigned char row[8];require(bool(stream.read(reinterpret_cast<char*>(row),8)),"complete original range row");uint32_t ordinal=little(row,4),index=little(row+4,2),stabilizer=row[6],ones=row[7];require(index>0&&index<=32&&ones<=1&&(stabilizer==1||stabilizer==2||stabilizer==3||stabilizer==6),"original roster fields");return{ordinal,index,stabilizer,ones};}
};
int main(int argc,char**argv){try{
 require(argc==10,"produce-or-check cache geometry q8-index roster begin end exact-TSV control");std::string mode=argv[1],control=argv[9];require((mode=="produce"||mode=="check")&&(control=="none"||control=="index"||control=="membership"),"exact range mode");uint64_t begin=std::stoull(argv[6]),end=std::stoull(argv[7]);require(begin<end&&end<=roster_rows,"declared nonempty original range");auto start=Clock::now();ScalarEngine engine(argv[2],argv[3],argv[4],mode=="check");Roster roster(argv[5],begin);std::ofstream out;std::ifstream in;if(mode=="produce")out=fresh(argv[8]);else{in.open(argv[8]);require(bool(in),"exact producer range input");}double loading=a19char::seconds(start),writing=0;uint64_t negative=0,zero=0,exceptional=0;uint32_t previous=0;bool have=false;
 for(uint64_t row=begin;row<end;++row){auto record=roster.next();require(!have||previous<record[0],"strict original range order");previous=record[0];have=true;auto ids=engine.atlas.unrank(record[0]);int expected_index=record[1];bool expected_ones=record[3];if(row==begin&&control=="index")++expected_index;if(row==begin&&control=="membership")expected_ones=!expected_ones;Q value=engine.alpha(ids,expected_index,expected_ones);negative+=value<0;zero+=value==0;exceptional+=!expected_ones;auto stamp=Clock::now();
  if(mode=="produce"){std::ostringstream encoded;encoded<<row<<'\t'<<record[0]<<'\t'<<record[1]<<'\t'<<value<<'\n';std::string bytes=encoded.str();require(uint64_t(out.tellp())+bytes.size()<=32ull*1024*1024,"declared exact TSV byte ceiling");out.write(bytes.data(),bytes.size());require(bool(out),"complete exact scalar row write");}
  else{std::string line;require(bool(std::getline(in,line)),"complete exact producer range");std::istringstream fields(line);uint64_t declared_row;uint32_t ordinal,index;std::string rational_text,tail;require(bool(fields>>declared_row>>ordinal>>index>>rational_text)&&!(fields>>tail),"exact four-column scalar row");require(declared_row==row&&ordinal==record[0]&&index==record[1],"every original scalar row identity");Q actual(rational_text);actual.canonicalize();require(actual.get_str()==rational_text,"canonical exact rational scalar encoding");require(actual==value,"independent unweighted and individual-character scalar equality");}writing+=a19char::seconds(stamp);}
 if(mode=="produce"){out.close();require(bool(out),"complete immutable range close");}else{std::string tail;require(!std::getline(in,tail)&&in.eof(),"no extra scalar range rows");}struct rusage usage{};require(getrusage(RUSAGE_SELF,&usage)==0,"actual native peak RSS");
 std::cout<<"{\"status\":\"PASS_EXACT_ORIGINAL_SCALAR_"<<(mode=="produce"?"RANGE":"CHECK")<<"\",\"begin\":"<<begin<<",\"end\":"<<end<<",\"rows\":"<<end-begin<<",\"negative\":"<<negative<<",\"zero\":"<<zero<<",\"exceptional\":"<<exceptional<<",\"proper_terms_each\":511,\"original_subset_lookups\":"<<engine.lookups_done<<",\"decoded_low_types\":"<<engine.low_cache.size()<<",\"cache_hits\":"<<engine.hits<<",\"cache_misses\":"<<engine.misses<<",\"seconds\":{\"loading\":"<<loading<<",\"lookup\":"<<engine.lookup_seconds<<",\"decode\":"<<engine.decode_seconds<<",\"transport\":"<<engine.transport_seconds<<",\"base\":"<<engine.base_seconds<<",\"correction\":"<<engine.correction_seconds<<",\"writing_or_exact_comparison\":"<<writing<<",\"complete\":"<<a19char::seconds(start)<<"},\"character_work\":{\"characters\":"<<engine.correction_stats.characters<<",\"orbits\":"<<engine.correction_stats.orbits<<",\"rational_terms\":"<<engine.correction_stats.terms<<",\"polar_states\":"<<engine.correction_stats.states<<",\"characters_seconds\":"<<engine.correction_stats.character_seconds<<",\"numerators_seconds\":"<<engine.correction_stats.numerator_seconds<<",\"projection_seconds\":"<<engine.correction_stats.projection_seconds<<"},\"peak_rss_bytes\":"<<usage.ru_maxrss<<"}\n";return 0;
 }catch(const std::exception&e){std::cerr<<"REFUSED: "<<e.what()<<'\n';return 2;}}
